import { parseAddress, formatAddress, expandRange } from './address.js'
import { literalValue } from './sheet.js'
import {
  num, bool, err, ZERO, isError, finite, toNumber, compareValues,
  DIV0, REF, VALUE, CYCLE, NAME, ERR,
} from './value.js'

const ARITY = { SUM: null, MIN: null, MAX: null, COUNT: null, AVG: null, ABS: 1, IF: 3 }

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.running = new Set()
  }

  /** The value of a cell, 0 when nobody declared it. */
  valueAt(address) {
    if (this.cache.has(address)) return this.cache.get(address)
    const cell = this.sheet.byAddress.get(address)
    if (cell === undefined) return ZERO
    if (this.running.has(address)) return err(CYCLE)
    this.running.add(address)
    let value
    try {
      value = cell.isFormula
        ? (cell.formula === null ? err(ERR) : this.evaluate(cell.formula))
        : literalValue(cell.content)
    } finally {
      this.running.delete(address)
    }
    this.cache.set(address, value)
    return value
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'boolean':
        return bool(node.value)
      case 'paren':
        return this.evaluate(node.inner)
      case 'range':
        return err(ERR)
      case 'reference': {
        const cell = parseAddress(node.name)
        if (cell === null) return err(REF)
        return this.valueAt(formatAddress(cell))
      }
      case 'unary':
        return this.evaluateUnary(node)
      case 'binary':
        return this.evaluateBinary(node)
      default:
        return this.evaluateCall(node)
    }
  }

  evaluateUnary(node) {
    const value = this.evaluate(node.operand)
    if (isError(value)) return value
    const n = toNumber(value)
    if (isError(n)) return n
    return finite(node.op === '-' ? -n.number : n.number)
  }

  evaluateBinary(node) {
    const left = this.evaluate(node.left)
    if (isError(left)) return left
    const right = this.evaluate(node.right)
    if (isError(right)) return right
    switch (node.op) {
      case '=':
        return bool(compareValues(left, right) === 0)
      case '<>':
        return bool(compareValues(left, right) !== 0)
      case '<':
        return bool(compareValues(left, right) < 0)
      case '<=':
        return bool(compareValues(left, right) <= 0)
      case '>':
        return bool(compareValues(left, right) > 0)
      case '>=':
        return bool(compareValues(left, right) >= 0)
      default:
        break
    }
    const a = toNumber(left)
    if (isError(a)) return a
    const b = toNumber(right)
    if (isError(b)) return b
    switch (node.op) {
      case '+':
        return finite(a.number + b.number)
      case '-':
        return finite(a.number - b.number)
      case '*':
        return finite(a.number * b.number)
      case '/':
