    const name = node.name.toUpperCase()
    if (!Object.prototype.hasOwnProperty.call(ARITY, name)) return err(NAME)
    const arity = ARITY[name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return err(ERR)

