export function dependencies(cell) {
  const found = new Map()
  if (cell.isFormula && cell.formula !== null) collect(cell.formula, found)
  return [...found.values()]
    .sort((a, b) => (a.col - b.col) || (a.row - b.row))
    .map(formatAddress)
