{"file_path":"src/schedule.js","content":"import { sortedNames } from './graph.js'

/**
 * Runs the graph on a fixed number of workers: at each instant every free
 * worker takes the ready task with the greatest priority, ties broken by
 * ascending name.
 */
export function pack(tasks, priority, workerCount) {
  const available = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finished = new Map()
  const pending = new Set(sortedNames(tasks))
  let time = 0
  let makespan = 0

  const ready = (name) => tasks.get(name).deps.every((d) => finished.has(d) && finished.get(d) <= time)

  while (pending.size > 0) {
    for (;;) {
      let worker = -1
      for (let i = 0; i < workerCount; i += 1) {
        if (available[i] <= time) {
          worker = i
          break
        }
      }
      if (worker < 0) break

      let chosen = null
      for (const name of pending) {
        if (!ready(name)) continue
        if (chosen === null || priority.get(name) > priority.get(chosen)) chosen = name
      }
      if (chosen === null) break

      const start = time
      const finish = start + tasks.get(chosen).cost
      runs[worker].push({ name: chosen, start, finish })
      available[worker] = finish
      finished.set(chosen, finish)
      pending.delete(chosen)
      if (finish > makespan) makespan = finish
    }

    if (pending.size === 0) break
    let next = null
    for (const at of available) {
      if (at > time && (next === null || at < next)) next = at
    }
    if (next === null) break
    time = next
  }

  return { runs, makespan }
}
"}

