 * The two limiter policies. Each keeps one independent state per key, and each
 * answers the same three questions: advance a key to a tick, would it allow a
 * request now, and record one.
 */

/**
 * A token bucket. Tokens are held scaled by the refill period, as whole units
 * of `1 / per` of a token, so that the fractions a partial period leaves
 * accumulate exactly instead of being rounded away.
 */
export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.scaledCapacity = capacity * per
    this.states = new Map()
  }

  /** The state of a key, created full and current as of `tick` when new. */
  stateOf(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { scaledTokens: this.scaledCapacity, tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateOf(key, tick)
    const elapsed = tick - state.tick
    if (elapsed > 0n) {
      const gained = this.refill * elapsed
      const scaledTokens = state.scaledTokens + gained
      state.scaledTokens = scaledTokens > this.scaledCapacity ? this.scaledCapacity : scaledTokens
      state.tick = tick
    }
  }

  allows(key, tick) {
    return this.stateOf(key, tick).scaledTokens >= this.per
  }

  record(key, tick) {
    const state = this.stateOf(key, tick)
    state.scaledTokens -= this.per
  }
}

/**
 * A sliding window. It remembers the ticks of the requests it recorded, and
 * covers the `span` ticks ending at the tick it was last advanced to.
 */
export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  stateOf(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [], head: 0 }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateOf(key)
    const cutoff = tick - this.span
    // Recorded ticks never go backwards, so the stale ones are a prefix.
    while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) {
      state.head += 1
    }
    if (state.head > 0) {
      state.ticks = state.ticks.slice(state.head)
      state.head = 0
    }
  }

  allows(key) {
    const state = this.stateOf(key)
    return BigInt(state.ticks.length - state.head) < this.limit
  }

  record(key, tick) {
    this.stateOf(key).ticks.push(tick)
  }
}
"}

