import { lineError } from './errors.js'
import { SlidingWindow, TokenBucket } from './policies.js'

/** Names, route prefixes and event keys all draw on the same characters. */
const TOKEN = /^[A-Za-z0-9_./:-]+$/

/** An unsigned decimal integer, without a sign and without a leading zero. */
const COUNT = /^(?:0|[1-9][0-9]*)$/

function isToken(word) {
  return TOKEN.test(word)
}

/**
 * The value of a count field, or a failure naming the field and its least
 * acceptable value.
 */
function readCount(lineNumber, word, field, least) {
  if (!COUNT.test(word)) {
    throw lineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(word)
  if (value < BigInt(least)) {
    throw lineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  return value
}

/** The lines of the file, without the empty tail a trailing newline leaves. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

export function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (events.length > 0) {
        throw lineError(lineNumber, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw lineError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityWord, refillWord, perWord] = words
      if (!isToken(name)) throw lineError(lineNumber, `invalid policy name ${name}`)
      const capacity = readCount(lineNumber, capacityWord, 'capacity', 1)
      const refill = readCount(lineNumber, refillWord, 'refill', 0)
      const per = readCount(lineNumber, perWord, 'per', 1)
      if (policies.has(name)) throw lineError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) {
        throw lineError(lineNumber, 'expected window <name> <limit> <span>')
      }
      const [, name, limitWord, spanWord] = words
      if (!isToken(name)) throw lineError(lineNumber, `invalid policy name ${name}`)
      const limit = readCount(lineNumber, limitWord, 'limit', 0)
      const span = readCount(lineNumber, spanWord, 'span', 1)
      if (policies.has(name)) throw lineError(lineNumber, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) {
        throw lineError(lineNumber, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      if (!isToken(prefix)) throw lineError(lineNumber, `invalid route prefix ${prefix}`)
      const named = []
      for (const name of words.slice(2)) {
        const policy = policies.get(name)
        if (policy === undefined) throw lineError(lineNumber, `unknown policy ${name}`)
        named.push(policy)
      }
      if (routes.has(prefix)) throw lineError(lineNumber, `prefix ${prefix} is routed twice`)
      routes.set(prefix, named)
    } else if (directive === 'event') {
      if (words.length !== 3) {
        throw lineError(lineNumber, 'expected event <tick> <key>')
      }
      const [, tickWord, key] = words
      const tick = readCount(lineNumber, tickWord, 'tick', 0)
      if (!isToken(key)) throw lineError(lineNumber, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw lineError(lineNumber, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key })
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  return { routes, events }
}
"}

