{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e6-cascade-share-t5/cell-9Hanqm/src/simulate.js","content":"/** The simulation: every event, in log order, against the policies it routes to. */

/**
 * The policies of the route that limits a key: the one whose prefix the key
 * starts with and which is longest among those that match, or none at all.
 */
function routeFor(routes, key) {
  let best = null
  let bestLength = -1
  for (const [prefix, policies] of routes) {
    if (key.startsWith(prefix) && prefix.length > bestLength) {
      best = policies
      bestLength = prefix.length
    }
  }
  return best === null ? [] : best
}

/**
 * The verdicts of the log, one per event: `{ tick, key, denier }`, where the
 * denier is the first policy on the route that refused, or null for an allow.
 */
export function simulate(routes, events) {
  const verdicts = []
  for (const { tick, key } of events) {
    const policies = routeFor(routes, key)
    for (const policy of policies) policy.advance(key, tick)
    let denier = null
    for (const policy of policies) {
      if (!policy.allows(key, tick)) {
        denier = policy
        break
      }
    }
    // Only a request every policy allows is recorded; a denial changes nothing.
    if (denier === null) {
      for (const policy of policies) policy.record(key, tick)
    }
    verdicts.push({ tick, key, denier })
  }
  return verdicts
}

export function formatReplay(verdicts) {
  let out = ''
  for (const { tick, key, denier } of verdicts) {
    out += denier === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${denier.name}\n`
  }
  return out
}

export function formatSummary(verdicts) {
  const perKey = new Map()
  let allowed = 0
  let denied = 0
  for (const { key, denier } of verdicts) {
    let counts = perKey.get(key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
    }
    if (denier === null) {
      counts.allowed += 1
      allowed += 1
    } else {
      counts.denied += 1
      denied += 1
    }
  }
  const keys = [...perKey.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const key of keys) {
    const counts = perKey.get(key)
    out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}
