/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './parser.js'
import { Engine, formatValue, depsOf, sortedCells } from './evaluator.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }
  const mode = argv[0]

  const { readFileSync } = await import('node:fs')
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const ordered = sortedCells(cells)
  const out = []

  if (mode === 'values') {
    const engine = new Engine(cells)
    for (const [name] of ordered) {
      out.push(`${name}=${formatValue(engine.valueOf(name))}\n`)
    }
  } else {
    for (const [name, cell] of ordered) {
      const deps = depsOf(cell.content)
      out.push(`${name}:${deps.map((d) => ' ' + d).join('')}\n`)
    }
  }

  process.stdout.write(out.join(''))
}

