{"file_path":"src/uri.js","content":"/**
 * URI parsing, normalization and resolution following RFC 3986's generic
 * syntax, with the normalization rules the task specifies.
 */

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21'
}

/** Thrown when a component holds a `%` without two hexadecimal digits. */
export class PercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Lowercase using ASCII rules only. */
function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/**
 * Parse a URI reference into its five generic components. An absent
 * component is null; an empty one is the empty string.
 */
export function parseURI(uri) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  let rest = uri

  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  const question = rest.indexOf('?')
  if (question !== -1) {
    query = rest.slice(question + 1)
    rest = rest.slice(0, question)
  }

  const colon = rest.indexOf(':')
  if (colon !== -1 && !rest.slice(0, colon).includes('/')) {
    scheme = rest.slice(0, colon)
    rest = rest.slice(colon + 1)
  }

  if (rest.startsWith('//')) {
    const after = rest.slice(2)
    const slash = after.indexOf('/')
    if (slash === -1) {
      authority = after
      path = ''
    } else {
      authority = after.slice(0, slash)
      path = after.slice(slash)
    }
  } else {
    path = rest
  }

  return { scheme, authority, path, query, fragment }
}

/** Serialize the five components back into a URI reference. */
export function formatURI(uri) {
  let out = ''
  if (uri.scheme !== null) out += uri.scheme + ':'
  if (uri.authority !== null) out += '//' + uri.authority
  out += uri.path
  if (uri.query !== null) out += '?' + uri.query
  if (uri.fragment !== null) out += '#' + uri.fragment
  return out
}

/** Split an authority into userinfo, host and port. */
export function parseAuthority(authority) {
  if (authority === null) return { userinfo: null, host: null, port: null }

  let userinfo = null
  let rest = authority

  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }

  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket === -1 ? 0 : bracket)

  if (colon === -1) return { userinfo, host: rest, port: null }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

function formatAuthority(userinfo, host, port) {
  let out = ''
  if (userinfo !== null) out += userinfo + '@'
  out += host
  if (port !== null) out += ':' + port
  return out
}

const HEX = /^[0-9A-Fa-f]{2}$/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercase the hexadecimal digits of every `%XX` and decode the triplets
 * that stand for an unreserved character.
 */
function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (hex.length < 2 || !HEX.test(hex)) throw new PercentError(component)
    const decoded = String.fromCharCode(parseInt(hex, 16))
    out += UNRESERVED.test(decoded) ? decoded : '%' + hex.toUpperCase()
    i += 2
  }
  return out
}

/** Remove dot segments from a path, per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  const output = []

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (end === -1) end = input.length
      output.push(input.slice(0, end))
      input = input.slice(end)
    }
  }

  return output.join('')
}

/**
 * Normalize a parsed URI reference and return the resulting string.
 * Throws a PercentError naming the first offending component.
 */
export function normalize(uri) {
  const scheme = uri.scheme === null ? null : asciiLower(uri.scheme)
  const { userinfo, host, port } = parseAuthority(uri.authority)

  let authority = null
  if (uri.authority !== null) {
    const newUserinfo =
      userinfo === null ? null : normalizePercent(userinfo, 'userinfo')
    const newHost = asciiLower(normalizePercent(host, 'host'))

    let newPort = port
    if (port !== null) {
      if (port === '' || (scheme !== null && DEFAULT_PORTS[scheme] === port)) {
        newPort = null
      }
    }

    authority = formatAuthority(newUserinfo, newHost, newPort)
  }

  let path = removeDotSegments(normalizePercent(uri.path, 'path'))
  if (uri.authority !== null && path === '') path = '/'

  const query = uri.query === null ? null : normalizePercent(uri.query, 'query')
  const fragment =
    uri.fragment === null ? null : normalizePercent(uri.fragment, 'fragment')

  return formatURI({ scheme, authority, path, query, fragment })
