/** Merge a relative reference path onto a base, per RFC 3986 section 5.3. */
function merge(base, refPath) {
  if (base.authority !== null && base.path === '') return '/' + refPath
  const slash = base.path.lastIndexOf('/')
  if (slash === -1) return refPath
  return base.path.slice(0, slash + 1) + refPath
}

/**
 * Resolve a parsed reference against a parsed base, strictly, and return the
 * parsed target (not yet normalized).
 */
export function resolve(base, ref) {
  const target = { scheme: null, authority: null, path: '', query: null, fragment: null }

  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== null) {
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== null ? ref.query : base.query
      } else {
        target.path = removeDotSegments(
          ref.path.startsWith('/') ? ref.path : merge(base, ref.path)
        )
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = ref.fragment
  return target
}
