{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseURI, normalize, resolve, PercentError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}
const mode = argv[0]

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const records = input.split('\n')
if (records.length > 0 && records[records.length - 1] === '') records.pop()

const out = []

for (let i = 0; i < records.length; i++) {
  const record = records[i]
  const n = i + 1

  try {
    if (mode === 'normalize') {
      out.push(normalize(parseURI(record)))
    } else {
      const space = record.indexOf(' ')
      if (space === -1) fail(`line ${n}: expected a base and a reference`)

      const base = parseURI(record.slice(0, space))
      if (base.scheme === null) fail(`line ${n}: the base has no scheme`)

      const ref = parseURI(record.slice(space + 1))
      out.push(normalize(resolve(base, ref)))
    }
  } catch (error) {
    if (error instanceof PercentError) fail(`line ${n}: ${error.message}`)
    throw error
  }
}

process.stdout.write(out.map((line) => line + '\n').join(''))
"}

