function formatJSON(obj) {
  return JSON.stringify(obj, null, 2) + '\n';
}

function formatKeys(obj, prefix = '') {
  const lines = [];

  const processValue = (value, path) => {
    if (value === null || value === undefined) {
      return;
    }

    const type = Array.isArray(value) ? 'array' : typeof value;

    if (type === 'object') {
      lines.push(`${path} table`);
      const keys = Object.keys(value).sort();
      for (const key of keys) {
        processValue(value[key], path ? `${path}.${key}` : key);
      }
    } else if (type === 'array') {
      // Check if it's an array of tables
      if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
        lines.push(`${path} array`);
        for (let i = 0; i < value.length; i++) {
          processValue(value[i], `${path}[${i}]`);
        }
      } else {
        lines.push(`${path} array`);
        for (let i = 0; i < value.length; i++) {
          const item = value[i];
          if (typeof item === 'number') {
            if (Number.isInteger(item)) {
              lines.push(`${path}[${i}] integer`);
            } else {
              lines.push(`${path}[${i}] float`);
            }
          } else if (typeof item === 'boolean') {
            lines.push(`${path}[${i}] boolean`);
          } else if (typeof item === 'string') {
            lines.push(`${path}[${i}] string`);
          } else if (Array.isArray(item)) {
            lines.push(`${path}[${i}] array`);
          } else if (typeof item === 'object') {
            lines.push(`${path}[${i}] table`);
          }
        }
      }
    } else if (type === 'number') {
      if (Number.isInteger(value)) {
        lines.push(`${path} integer`);
      } else {
        lines.push(`${path} float`);
      }
    } else if (type === 'boolean') {
      lines.push(`${path} boolean`);
    } else if (type === 'string') {
      lines.push(`${path} string`);
    }
  };

