 * The parser for the configuration document. It turns the lines of the
 * document into a tree of tagged nodes:
 *
 *   { kind: 'table',   value: Map<string, node> }
 *   { kind: 'array',   value: node[], tables: boolean }
 *   { kind: 'string',  value: string }
 *   { kind: 'integer', value: number }
 *   { kind: 'float',   value: number }
 *   { kind: 'boolean', value: boolean }
 *
 * Tables are held in a Map so that any key text, `__proto__` included, is
 * carried faithfully and in the order it arrived; the printers sort.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const BARE = /[A-Za-z0-9_-]/
const INTEGER = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/
const HEX4 = /^[0-9a-fA-F]{4}$/

function newTable() {
  return { kind: 'table', value: new Map() }
}

function newArray(tables) {
  return { kind: 'array', value: [], tables }
}

function isSpace(c) {
  return c === ' ' || c === '\t'
}

function isComment(c) {
  return c === '#' || c === ';'
}

/** Joins a path prefix and a key with a dot, the root prefix being empty. */
function joinKey(prefix, key) {
  return prefix === '' ? key : `${prefix}.${key}`
}

/** A scanner over one line of the document. */
class Line {
  constructor(text, number) {
    this.text = text
    this.number = number
    this.pos = 0
  }

  fail(reason) {
    throw new ParseError(this.number, reason)
  }

  done() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.text[this.pos]
  }

  next() {
    return this.text[this.pos++]
  }

  skipSpace() {
    while (!this.done() && isSpace(this.peek())) this.pos += 1
  }

  /** True once nothing but a comment is left. */
  atEnd() {
    return this.done() || isComment(this.peek())
  }

  // --- names ---------------------------------------------------------------

  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const start = this.pos
    while (!this.done() && BARE.test(this.peek())) this.pos += 1
    if (this.pos === start) this.fail('expected a name')
    return this.text.slice(start, this.pos)
  }

  dottedName() {
    const names = [this.name()]
    for (;;) {
      const mark = this.pos
      this.skipSpace()
      if (this.peek() !== '.') {
        this.pos = mark
        return names
      }
      this.pos += 1
      this.skipSpace()
      names.push(this.name())
    }
  }

  // --- strings -------------------------------------------------------------

  basicString() {
    this.pos += 1
    let out = ''
    for (;;) {
      if (this.done()) this.fail('unterminated string')
      const c = this.next()
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.done()) this.fail('unterminated string')
      const e = this.next()
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const hex = this.text.slice(this.pos, this.pos + 4)
        if (!HEX4.test(hex)) this.fail('invalid escape \\u')
        this.pos += 4
        out += String.fromCharCode(parseInt(hex, 16))
      } else this.fail(`invalid escape \\${e}`)
    }
  }

  literalString() {
    this.pos += 1
    const start = this.pos
    while (!this.done()) {
      if (this.next() === "'") return this.text.slice(start, this.pos - 1)
    }
    this.fail('unterminated string')
  }

  // --- values --------------------------------------------------------------

  /**
   * Reads one value. `path` is where the value lands, counted from the root,
   * so that an inline table can name a doubled key in full.
   */
  value(path) {
    this.skipSpace()
    if (this.done()) this.fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}' || isComment(c)) this.fail('expected a value')
    if (c === '"') return { kind: 'string', value: this.basicString() }
    if (c === "'") return { kind: 'string', value: this.literalString() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inlineTable(path)
    return this.bareValue()
  }

  /**
   * Reads a boolean or a number. The run stops at a space, a tab, a comma, a
   * bracket, a brace or a `;`, so a `#` a value runs into belongs to its text
   * and makes it invalid.
   */
  bareValue() {
    const start = this.pos
    while (!this.done()) {
      const c = this.peek()
      if (isSpace(c) || c === ',' || c === ']' || c === '}' || c === ';') break
      this.pos += 1
    }
    const text = this.text.slice(start, this.pos)
    if (text === 'true') return { kind: 'boolean', value: true }
    if (text === 'false') return { kind: 'boolean', value: false }
    const digits = text.replace(/_/g, '')
    if (INTEGER.test(text)) return { kind: 'integer', value: Number(digits) }
    if (FLOAT.test(text)) return { kind: 'float', value: Number(digits) }
    this.fail(`invalid value ${text}`)
  }

  array(path) {
    this.pos += 1
    const array = newArray(false)
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ']') {
        this.pos += 1
        return array
      }
      array.value.push(this.value(`${path}[${array.value.length}]`))
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.peek() === ',') {
        this.pos += 1
        continue
      }
      if (this.peek() === ']') {
        this.pos += 1
        return array
      }
      this.fail('unterminated array')
    }
  }

  inlineTable(path) {
    this.pos += 1
    const table = newTable()
    this.skipSpace()
    if (!this.done() && this.peek() === '}') {
      this.pos += 1
      return table
    }
    for (;;) {
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dottedName()
      this.skipSpace()
      if (this.done() || this.peek() !== '=') this.fail('expected = in an inline table')
      this.pos += 1
      const target = this.place(table, names, path)
      const value = this.value(target.path)
      target.table.value.set(target.key, value)
      this.skipSpace()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.peek() === ',') {
        this.pos += 1
        continue
      }
      if (this.peek() === '}') {
        this.pos += 1
        return table
      }
      this.fail('unterminated inline table')
    }
  }

  // --- assignment ----------------------------------------------------------

  /**
   * Walks a dotted name from `table`, creating the tables it passes through,
   * and reports where the last name should land. `prefix` is the path of
   * `table` counted from the root.
   */
  place(table, names, prefix) {
    let node = table
    let path = prefix
    for (let i = 0; i < names.length - 1; i += 1) {
      path = joinKey(path, names[i])
      node = this.step(node, names[i], path)
    }
    const key = names[names.length - 1]
    path = joinKey(path, key)
    if (node.value.has(key)) this.fail(`key ${path} is defined twice`)
    return { table: node, key, path }
  }

  /** One step of a walk: through a table, or the last table of an array. */
  step(node, name, path) {
    const held = node.value.get(name)
    if (held === undefined) {
      const made = newTable()
      node.value.set(name, made)
      return made
    }
    if (held.kind === 'table') return held
    if (held.kind === 'array' && held.tables && held.value.length > 0) {
      return held.value[held.value.length - 1]
    }
    this.fail(`${path} is not a table`)
  }
}

export function parseDocument(lines) {
  const root = newTable()
  const headed = new Set()
  let current = root
  let currentPath = ''

  for (let i = 0; i < lines.length; i += 1) {
    const line = new Line(lines[i], i + 1)
    line.skipSpace()
    if (line.atEnd()) continue

    if (line.peek() === '[') {
      const header = readHeader(line)
      const { names, tables } = header
      let node = root
      let path = ''
      for (let j = 0; j < names.length - 1; j += 1) {
        path = joinKey(path, names[j])
        node = line.step(node, names[j], path)
      }
      const key = names[names.length - 1]
      path = joinKey(path, key)
      const held = node.value.get(key)

      if (tables) {
        let array = held
        if (array === undefined) {
          array = newArray(true)
          node.value.set(key, array)
        } else if (array.kind !== 'array' || !array.tables) {
          line.fail(`${path} is not an array of tables`)
        }
        const made = newTable()
        array.value.push(made)
        current = made
      } else {
        let table = held
        if (table === undefined) {
          table = newTable()
          node.value.set(key, table)
        } else if (table.kind !== 'table') {
          line.fail(`${path} is not a table`)
        }
        if (headed.has(table)) line.fail(`table ${path} is defined twice`)
        headed.add(table)
        current = table
      }
      currentPath = path
      continue
    }

    const names = line.dottedName()
    line.skipSpace()
    if (line.done() || line.peek() !== '=') line.fail('expected key = value')
    line.pos += 1
    const target = line.place(current, names, currentPath)
    const value = line.value(target.path)
    line.skipSpace()
    if (!line.atEnd()) line.fail('trailing text after a value')
    target.table.value.set(target.key, value)
  }

  return root
}

function readHeader(line) {
  line.pos += 1
  let tables = false
  if (line.peek() === '[') {
    tables = true
    line.pos += 1
  }
  line.skipSpace()
  const names = line.dottedName()
  line.skipSpace()
  if (line.peek() !== ']') line.fail('unterminated table header')
  line.pos += 1
  if (tables) {
    if (line.peek() !== ']') line.fail('unterminated table header')
    line.pos += 1
  }
  line.skipSpace()
  if (!line.atEnd()) line.fail('trailing text after a table header')
  return { names, tables }
}
"}

