{"file_path":"src/format.js","content":"/** The two printers: canonical JSON, and one line per node with its type. */

/** Orders two keys by code point rather than by UTF-16 code unit. */
export function compareKeys(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length - right.length
}

function sortedKeys(table) {
  return Array.from(table.value.keys()).sort(compareKeys)
}

function render(node, indent) {
  const inner = `${indent}  `
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const members = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${render(node.value.get(key), inner)}`
    )
    return `{\n${members.join(',\n')}\n${indent}}`
  }
  if (node.kind === 'array') {
    if (node.value.length === 0) return '[]'
    const items = node.value.map((item) => `${inner}${render(item, inner)}`)
    return `[\n${items.join(',\n')}\n${indent}]`
  }
  return JSON.stringify(node.value)
}

export function toJson(root) {
  return `${render(root, '')}\n`
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.kind === 'table') {
      for (const key of sortedKeys(node)) {
        const child = node.value.get(key)
        const childPath = path === '' ? key : `${path}.${key}`
        lines.push(`${childPath} ${child.kind}`)
        walk(child, childPath)
      }
    } else if (node.kind === 'array') {
      node.value.forEach((item, index) => {
        const childPath = `${path}[${index}]`
        lines.push(`${childPath} ${item.kind}`)
        walk(item, childPath)
      })
    }
  }
  walk(root, '')
  return lines.map((line) => `${line}\n`).join('')
}
"}

