{"file_path":"src/evaluate.js","content":"/**
 * Evaluating the sheet: what a literal means, what a formula computes, and
 * which cells a cell's content names.
 */

import { addressName, compareAddresses, parseAddress } from './address.js'
import { parseFormula, rangesArePlaced } from './formula.js'
import {
  CYCLE,
  DIV0,
  ERR,
  ERROR_TOKENS,
  NAME,
  REF,
  bool,
  compareValues,
  err,
  finite,
  isError,
  num,
  text,
  toCondition,
  toNumber,
} from './value.js'

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

/** Read a literal: empty is zero, a number is that number, an error token is that error. */
export function readLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** The parsed form of a cell's content, computed once per cell. */
function contentOf(cell) {
  if (cell.parsed !== undefined) return cell.parsed
  if (cell.content.startsWith('=')) {
    const tree = parseFormula(cell.content.slice(1))
    cell.parsed = tree === null ? { kind: 'broken' } : { kind: 'formula', tree }
  } else {
    cell.parsed = { kind: 'literal', value: readLiteral(cell.content) }
  }
  return cell.parsed
}

/** Expand a range into the cells it covers, in column and then row order. */
function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const lowColumn = Math.min(from.column, to.column)
  const highColumn = Math.max(from.column, to.column)
  const lowRow = Math.min(from.row, to.row)
  const highRow = Math.max(from.row, to.row)
  for (let column = lowColumn; column <= highColumn; column += 1) {
    for (let row = lowRow; row <= highRow; row += 1) {
      cells.push({ column, row, name: addressName(column, row) })
    }
  }
  return cells
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.values = new Map()
    this.visiting = new Set()
  }

  /** The value of the cell at an upper-cased address; an undeclared cell is zero. */
  valueAt(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return num(0)
    if (this.visiting.has(name)) return CYCLE
    this.visiting.add(name)
    let value
    try {
      value = this.evaluateCell(cell)
    } finally {
      this.visiting.delete(name)
    }
    this.values.set(name, value)
    return value
  }

  evaluateCell(cell) {
    const parsed = contentOf(cell)
    if (parsed.kind === 'literal') return parsed.value
    if (parsed.kind === 'broken') return ERR
    if (!rangesArePlaced(parsed.tree)) return ERR
    return this.evaluate(parsed.tree)
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'boolean':
        return bool(node.value)
      case 'group':
        return this.evaluate(node.inner)
      case 'ref': {
        const address = parseAddress(node.word)
        if (address === null) return REF
        return this.valueAt(address.name)
      }
      case 'range':
        return ERR
      case 'unary': {
        const operand = toNumber(this.evaluate(node.operand))
        if (isError(operand)) return operand
        return finite(node.op === '-' ? -operand.value : operand.value)
      }
      case 'binary':
        return this.binary(node)
      case 'call':
        return this.call(node)
      default:
        return ERR
    }
  }

  binary(node) {
    const left = this.evaluate(node.left)
    if (isError(left)) return left
    const right = this.evaluate(node.right)
    if (isError(right)) return right

    if (node.op === '=' || node.op === '<>' || node.op === '<' || node.op === '<=' ||
        node.op === '>' || node.op === '>=') {
      const order = compareValues(left, right)
      switch (node.op) {
        case '=': return bool(order === 0)
        case '<>': return bool(order !== 0)
        case '<': return bool(order < 0)
        case '<=': return bool(order <= 0)
        case '>': return bool(order > 0)
        default: return bool(order >= 0)
      }
    }

    const x = toNumber(left)
    if (isError(x)) return x
    const y = toNumber(right)
    if (isError(y)) return y
    switch (node.op) {
      case '+': return finite(x.value + y.value)
      case '-': return finite(x.value - y.value)
      case '*': return finite(x.value * y.value)
      case '/': return y.value === 0 ? DIV0 : finite(x.value / y.value)
      default: return finite(x.value ** y.value)
    }
  }

  /** The values an argument contributes: a range contributes every cell it covers. */
  argumentValues(node) {
    if (node.type !== 'range') return [this.evaluate(node)]
    const cells = rangeCells(node)
    if (cells === null) return [REF]
    return cells.map((cell) => this.valueAt(cell.name))
  }

  call(node) {
    const { name, args } = node
    if (name === 'IF') {
      if (args.length !== 3) return ERR
      const condition = toCondition(this.argumentValues(args[0])[0])
      if (isError(condition)) return condition
      return this.argumentValues(args[condition.value ? 1 : 2])[0]
    }
    if (name === 'ABS') {
      if (args.length !== 1) return ERR
    } else if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) {
      if (args.length < 1) return ERR
    } else {
      return NAME
    }

    const values = []
    for (const arg of args) values.push(...this.argumentValues(arg))
    for (const value of values) {
      if (isError(value)) return value
    }

    if (name === 'COUNT') {
      return num(values.filter((value) => value.kind === 'number').length)
    }

    const numbers = []
    for (const value of values) {
      const asNumber = toNumber(value)
      if (isError(asNumber)) return asNumber
      numbers.push(asNumber.value)
    }
    switch (name) {
      case 'ABS': return finite(Math.abs(numbers[0]))
      case 'SUM': return finite(numbers.reduce((total, one) => total + one, 0))
      case 'MIN': return finite(Math.min(...numbers))
      case 'MAX': return finite(Math.max(...numbers))
      default: {
        const total = numbers.reduce((sum, one) => sum + one, 0)
        return numbers.length === 0 ? DIV0 : finite(total / numbers.length)
      }
    }
  }
}

/**
 * The distinct cells a cell's content names directly, ranges expanded and only
 * addresses inside the addressable range named.
 */
export function dependencies(cell) {
  const parsed = contentOf(cell)
  if (parsed.kind !== 'formula') return []
  const found = new Map()
  const walk = (node) => {
    switch (node.type) {
      case 'ref': {
        const address = parseAddress(node.word)
        if (address !== null) found.set(address.name, address)
        break
      }
      case 'range': {
        const cells = rangeCells(node)
        if (cells !== null) for (const one of cells) found.set(one.name, one)
        break
      }
      case 'group':
        walk(node.inner)
        break
      case 'unary':
        walk(node.operand)
        break
      case 'binary':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }
  walk(parsed.tree)
  return [...found.values()].sort(compareAddresses).map((address) => address.name)
}
"}

