            throw new Error(`error: line ${this.lineNum + 1}: ${this.pathToString(fullPath)} is not an array of tables`)
          }

          const newTable = {}
          target[name].push(newTable)
          this.current = newTable
          this.path = fullPath
        } else {
          if (!(name in target)) {
            target[name] = {}
          } else if (typeof target[name] !== 'object' || Array.isArray(target[name])) {
            throw new Error(`error: line ${this.lineNum + 1}: ${this.pathToString(fullPath)} is not a table`)
          }

          // Check if this table was already explicitly defined as a header
          if (this.isTableExplicitlyDefined(target[name])) {
            throw new Error(`error: line ${this.lineNum + 1}: table ${this.pathToString(fullPath)} is defined twice`)
          }

          target[name]._explicit = true
          this.current = target[name]
          this.path = fullPath
        }
      } else {
        // Intermediate element
        if (!(name in target)) {
          target[name] = {}
        } else if (typeof target[name] !== 'object' || Array.isArray(target[name])) {
          throw new Error(`error: line ${this.lineNum + 1}: ${this.pathToString(fullPath)} is not a table`)
        }

        target = target[name]
      }
    }
  }

  isTableExplicitlyDefined(table) {
    return table._explicit === true
  }

  pathToString(path) {
    return path.join('.')
  }
}

// Read command line arguments
const args = process.argv.slice(2)

if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
const input = fs.readFileSync(0, 'utf-8')

try {
  const parser = new TOMLParser(input)
  const data = parser.parse()

  if (mode === 'json') {
    const json = JSON.stringify(data, Object.keys(data).sort(), 2)
    process.stdout.write(json + '\n')
  } else {
    // keys mode
    const lines = []
    printKeys(data, '', lines)
    lines.forEach(line => process.stdout.write(line + '\n'))
  }

  process.exit(0)
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

function printKeys(obj, path, lines) {
  const keys = Object.keys(obj).sort()
  for (const key of keys) {
    const fullPath = path ? path + '.' + key : key
    const value = obj[key]
    const type = getType(value)
    lines.push(`${fullPath} ${type}`)
    if (type === 'table') {
      printKeys(value, fullPath, lines)
    } else if (type === 'array' && Array.isArray(value) && value.length > 0 && typeof value[0] === 'object') {
      // Array of tables
      for (let i = 0; i < value.length; i++) {
        const indexPath = `${fullPath}[${i}]`
        printKeys(value[i], indexPath, lines)
      }
    }
  }
}

function getType(value) {
  if (Array.isArray(value)) {
    if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
      return 'array'
    }
    return 'array'
  }
  if (typeof value === 'object' && value !== null) {
    return 'table'
  }
  if (typeof value === 'boolean') {
    return 'boolean'
  }
  if (typeof value === 'string') {
    return 'string'
  }
  if (Number.isInteger(value)) {
    return 'integer'
  }
  return 'float'
}
"}

