{"file_path":"src/parse.js","content":"/**
 * Parsing of the build-graph input format.
 *
 * A line is trimmed, then ignored when it is empty or starts with `#`.
 * Otherwise it is split on runs of whitespace and read as a directive.
 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/** An input error that carries the message the command must print. */
export class InputError extends Error {
  constructor(message, code = 2) {
    super(message)
    this.name = 'InputError'
    this.code = code
  }
}

export function isValidName(word) {
  return NAME_RE.test(word)
}

/**
 * Split the raw standard input into lines, dropping the single empty tail that
 * a trailing newline leaves behind.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Read the graph. Returns `{ names, costs, deps }` where `names` is in
 * ascending order, `costs` maps a name to its cost and `deps` maps a name to
 * its ascending, duplicate-free dependency list.
 *
 * Throws an `InputError` on the first malformed line, or on the first
 * dependency name in input order that no `task` line declares.
 */
export function parseGraph(text) {
  const costs = new Map()
  const declaredAt = new Map()
  const depSets = new Map()
  // Every name a `dep` line uses, in input order, so an unknown one can be
  // reported in that same order once the whole input has been read.
  const references = []

  const lines = splitLines(text)
  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new InputError(`error: line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      if (!isValidName(name)) {
        throw new InputError(`error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(cost)) {
        throw new InputError(`error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (declaredAt.has(name)) {
        throw new InputError(`error: line ${lineNo}: task ${name} is declared twice`)
      }
      declaredAt.set(name, lineNo)
      costs.set(name, Number(cost))
      if (!depSets.has(name)) depSets.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new InputError(`error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      for (let w = 1; w < words.length; w += 1) {
        if (!isValidName(words[w])) {
          throw new InputError(`error: line ${lineNo}: invalid task name ${words[w]}`)
        }
      }
      const subject = words[1]
      for (let w = 1; w < words.length; w += 1) references.push(words[w])
      if (!depSets.has(subject)) depSets.set(subject, new Set())
      const set = depSets.get(subject)
      for (let w = 2; w < words.length; w += 1) set.add(words[w])
    } else {
      throw new InputError(`error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!costs.has(name)) throw new InputError(`error: unknown task ${name}`)
  }

  const names = [...costs.keys()].sort(compareNames)
  const deps = new Map()
  for (const name of names) {
    const set = depSets.get(name) ?? new Set()
    deps.set(name, [...set].sort(compareNames))
  }
  return { names, costs, deps }
}

/** Ascending order over names, by code unit so it is stable everywhere. */
export function compareNames(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}
"}

