 * The scanner. `scan(text)` turns source text into an array of tokens, or
 * throws a `ScanError` carrying the position and the reason of the first
 * failure it meets.
 */

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const TAB_WIDTH = 4

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || isDecDigit(c) || c === '_')
}

function isHexDigit(c) {
  return c !== undefined && (isDecDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function digitTest(base) {
  if (base === 16) return isHexDigit
  if (base === 2) return (c) => c === '0' || c === '1'
  if (base === 8) return (c) => c !== undefined && c >= '0' && c <= '7'
  return isDecDigit
}

/** A cursor over the code points of the source, tracking line and column. */
class Cursor {
  constructor(text) {
    this.cps = Array.from(text)
    this.lines = new Array(this.cps.length)
    this.cols = new Array(this.cps.length)
    let line = 1
    let col = 1
    for (let i = 0; i < this.cps.length; i++) {
      this.lines[i] = line
      this.cols[i] = col
      const c = this.cps[i]
      if (c === '\n') {
        line += 1
        col = 1
      } else if (c === '\t') {
        col = Math.floor((col - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
      } else {
        col += 1
      }
    }
    this.endLine = line
    this.endCol = col
  }

  at(i) {
    return this.cps[i]
  }

  get length() {
    return this.cps.length
  }

  line(i) {
    return i < this.cps.length ? this.lines[i] : this.endLine
  }

  col(i) {
    return i < this.cps.length ? this.cols[i] : this.endCol
  }

  slice(from, to) {
    return this.cps.slice(from, to).join('')
  }

  fail(i, reason) {
    throw new ScanError(this.line(i), this.col(i), reason)
  }
}

/** Scans the source text and returns its tokens. */
export function scan(text) {
  const cur = new Cursor(text)
  const tokens = []
  let i = 0

  while (i < cur.length) {
    const c = cur.at(i)

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i += 1
      continue
    }

    if (c === '/' && cur.at(i + 1) === '/') {
      i += 2
      while (i < cur.length && cur.at(i) !== '\n') i += 1
      continue
    }

    if (c === '/' && cur.at(i + 1) === '*') {
      i = skipBlockComment(cur, i)
      continue
    }

    const start = i
    const line = cur.line(start)
    const column = cur.col(start)

    if (c === 'r' && cur.at(i + 1) === '"') {
      const result = scanRawString(cur, i)
      tokens.push({ line, column, kind: 'rawstring', text: result.text, value: result.value })
      i = result.next
      continue
    }

    if (isIdentStart(c)) {
      let j = i + 1
      while (isIdentPart(cur.at(j))) j += 1
      const word = cur.slice(i, j)
      tokens.push({ line, column, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', text: word })
      i = j
      continue
    }

    if (isDecDigit(c)) {
      const result = scanNumber(cur, i)
      tokens.push({ line, column, kind: 'number', text: result.text })
      i = result.next
      continue
    }

    if (c === '"') {
      const result = scanString(cur, i)
      tokens.push({ line, column, kind: 'string', text: result.text, value: result.value })
      i = result.next
      continue
    }

    const two = cur.slice(i, i + 2)
    if (PUNCT2.includes(two)) {
      tokens.push({ line, column, kind: 'punct', text: two })
      i += 2
      continue
    }

    if (PUNCT1.includes(c)) {
      tokens.push({ line, column, kind: 'punct', text: c })
      i += 1
      continue
    }

    cur.fail(i, `unexpected character ${c}`)
  }

  return tokens
}

/** Skips a nesting block comment starting at `start`, returning the next index. */
function skipBlockComment(cur, start) {
  let depth = 0
  let i = start
  while (i < cur.length) {
    if (cur.at(i) === '/' && cur.at(i + 1) === '*') {
      depth += 1
      i += 2
      continue
    }
    if (cur.at(i) === '*' && cur.at(i + 1) === '/') {
      depth -= 1
      i += 2
      if (depth === 0) return i
      continue
    }
    i += 1
  }
  cur.fail(start, 'unterminated block comment')
}

/** Scans a number starting at `start`, which sits on a decimal digit. */
function scanNumber(cur, start) {
  let i = start

  const prefix = cur.at(start) === '0' ? cur.at(start + 1) : undefined
  let base = 10
  if (prefix === 'x' || prefix === 'X') base = 16
  else if (prefix === 'b' || prefix === 'B') base = 2
  else if (prefix === 'o' || prefix === 'O') base = 8

  if (base !== 10) {
    i = start + 2
    const consumed = scanDigitRun(cur, i, base)
    if (consumed === i) failNumber(cur, start, i)
    i = consumed
  } else {
    i = scanDigitRun(cur, i, 10)
    if (cur.at(i) === '.' && isDecDigit(cur.at(i + 1))) {
      i = scanDigitRun(cur, i + 1, 10)
    }
    const e = cur.at(i)
    if (e === 'e' || e === 'E') {
      const sign = cur.at(i + 1)
      if (isDecDigit(sign)) {
        i = scanDigitRun(cur, i + 1, 10)
      } else if ((sign === '+' || sign === '-') && isDecDigit(cur.at(i + 2))) {
        i = scanDigitRun(cur, i + 2, 10)
      }
    }
  }

  if (isIdentPart(cur.at(i))) failNumber(cur, start, i)

  return { text: cur.slice(start, i), next: i }
}

/**
 * Consumes a run of digits of `base` starting at `i`, where a `_` is allowed
 * only between two digits of the run. Returns the index after the run.
 */
function scanDigitRun(cur, i, base) {
  const isDigit = digitTest(base)
  let j = i
  while (j < cur.length) {
    const c = cur.at(j)
    if (isDigit(c)) {
      j += 1
      continue
    }
    if (c === '_' && j > i && isDigit(cur.at(j - 1)) && isDigit(cur.at(j + 1))) {
      j += 1
      continue
    }
    break
  }
  return j
}

/** Reports a bad number, swallowing the characters that trail it. */
function failNumber(cur, start, i) {
  let j = i
  while (isIdentPart(cur.at(j))) j += 1
  cur.fail(start, `invalid number ${cur.slice(start, j)}`)
}

/** Scans a raw string whose `r` sits at `start`. */
function scanRawString(cur, start) {
  let i = start + 2
  while (i < cur.length && cur.at(i) !== '"') i += 1
  if (i >= cur.length) cur.fail(start, 'unterminated string')
  return { text: cur.slice(start, i + 1), value: cur.slice(start + 2, i), next: i + 1 }
}

/** Scans a quoted string whose opening quote sits at `start`. */
function scanString(cur, start) {
  let i = start + 1
  let value = ''
  while (true) {
    if (i >= cur.length) cur.fail(start, 'unterminated string')
    const c = cur.at(i)
    if (c === '"') {
      return { text: cur.slice(start, i + 1), value, next: i + 1 }
    }
    if (c === '\n') cur.fail(i, 'newline in string')
    if (c !== '\\') {
      value += c
      i += 1
      continue
    }
    const escape = cur.at(i + 1)
    if (escape === undefined) cur.fail(start, 'unterminated string')
    const bad = () => cur.fail(i, `invalid escape \\${escape}`)
    if (escape === 'n') value += '\n'
    else if (escape === 't') value += '\t'
    else if (escape === 'r') value += '\r'
    else if (escape === '\\') value += '\\'
    else if (escape === '"') value += '"'
    else if (escape === '0') value += '\0'
    else if (escape === 'x') {
      const hi = cur.at(i + 2)
      const lo = cur.at(i + 3)
      if (!isHexDigit(hi) || !isHexDigit(lo)) bad()
      value += String.fromCharCode(parseInt(hi + lo, 16))
      i += 4
      continue
    } else if (escape === 'u') {
      if (cur.at(i + 2) !== '{') bad()
      let j = i + 3
      let digits = ''
      while (isHexDigit(cur.at(j))) {
        digits += cur.at(j)
        j += 1
      }
      if (digits.length === 0 || cur.at(j) !== '}') bad()
      const code = parseInt(digits, 16)
      if (!(code <= 0x10ffff)) bad()
      value += String.fromCodePoint(code)
      i = j + 1
      continue
    } else bad()
    i += 2
  }
}
"}

