{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and reference resolution following
 * RFC 3986's generic syntax.
 *
 * A parsed reference is a plain object whose components are either strings or
 * `undefined`. `undefined` means the component is absent, which is different
 * from a component that is present and empty: `http://a/b?` carries an empty
 * query while `http://a/b` carries none.
 */

const UNRESERVED = /[A-Za-z0-9\-._~]/
const HEX = /[0-9A-Fa-f]/

/** Lowercase using ASCII rules only, leaving every other code point alone. */
export function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.charCodeAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 0x20) : ch
  }
  return out
}

/** The default port of a scheme, or `undefined` when it has none. */
export function defaultPort(scheme) {
  switch (scheme) {
    case 'http':
    case 'ws':
      return '80'
    case 'https':
    case 'wss':
      return '443'
    case 'ftp':
      return '21'
    default:
      return undefined
  }
}

/**
 * Split a URI reference into scheme, authority, path, query and fragment.
 * The authority, when present, is split further into userinfo, host and port.
 */
export function parse(reference) {
  let rest = reference
  let scheme

  // The scheme runs to the first ':', which no '/', '?' or '#' may precede.
  for (let i = 0; i < rest.length; i += 1) {
    const ch = rest[i]
    if (ch === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (ch === '/' || ch === '?' || ch === '#') break
  }

  let fragment
  const hash = rest.indexOf('#')
  if (hash >= 0) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query
  const mark = rest.indexOf('?')
  if (mark >= 0) {
    query = rest.slice(mark + 1)
    rest = rest.slice(0, mark)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i += 1) {
      if (rest[i] === '/') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  const uri = { scheme, path: rest, query, fragment }
  Object.assign(uri, splitAuthority(authority))
  return uri
}

/** Split an authority into userinfo, host and port. */
function splitAuthority(authority) {
  if (authority === undefined) {
    return { authority: undefined, userinfo: undefined, host: undefined, port: undefined }
  }
  let rest = authority
  let userinfo
  const at = rest.lastIndexOf('@')
  if (at >= 0) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }
  let port
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon >= 0) {
    port = rest.slice(colon + 1)
    rest = rest.slice(0, colon)
  }
  return { authority, userinfo, host: rest, port }
}

/** Rebuild the authority from userinfo, host and port. */
function joinAuthority(uri) {
  if (uri.host === undefined) return undefined
  let out = ''
  if (uri.userinfo !== undefined) out += `${uri.userinfo}@`
  out += uri.host
  if (uri.port !== undefined) out += `:${uri.port}`
  return out
}

/** Reassemble a parsed reference into its string form. */
export function recompose(uri) {
  let out = ''
  if (uri.scheme !== undefined) out += `${uri.scheme}:`
  const authority = joinAuthority(uri)
  if (authority !== undefined) out += `//${authority}`
  out += uri.path
  if (uri.query !== undefined) out += `?${uri.query}`
  if (uri.fragment !== undefined) out += `#${uri.fragment}`
  return out
}

/**
 * The name of the first component carrying a truncated percent-encoding, or
 * `undefined` when every component is well formed. The components are checked
 * in the order path, userinfo, host, query, fragment.
 */
export function truncatedPercent(uri) {
  const order = ['path', 'userinfo', 'host', 'query', 'fragment']
  for (const name of order) {
    const value = uri[name]
    if (value !== undefined && hasTruncatedPercent(value)) return name
  }
  return undefined
}

function hasTruncatedPercent(text) {
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') continue
    if (i + 2 >= text.length) return true
    if (!HEX.test(text[i + 1]) || !HEX.test(text[i + 2])) return true
  }
  return false
}

/**
 * Uppercase the hexadecimal digits of every percent-encoded triplet and decode
 * those that stand for an unreserved character. The text must already be free
 * of truncated triplets.
 */
export function normalizePercent(text) {
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '%') {
      out += text[i]
      continue
    }
    const digits = text.slice(i + 1, i + 3).toUpperCase()
    const decoded = String.fromCharCode(parseInt(digits, 16))
    out += UNRESERVED.test(decoded) ? decoded : `%${digits}`
    i += 2
  }
  return out
}

/** Remove dot segments from a path, following RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = `/${input.slice(3)}`
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      output = dropLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = dropLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const start = input[0] === '/' ? 1 : 0
      let end = input.indexOf('/', start)
      if (end < 0) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }
  return output
}

function dropLastSegment(output) {
  const slash = output.lastIndexOf('/')
  return slash < 0 ? '' : output.slice(0, slash)
}

/** Normalize a parsed reference in place and return it. */
export function normalize(uri) {
  const result = { ...uri }

  if (result.scheme !== undefined) result.scheme = asciiLower(result.scheme)

  for (const name of ['userinfo', 'host', 'path', 'query', 'fragment']) {
    if (result[name] !== undefined) result[name] = normalizePercent(result[name])
  }

  if (result.host !== undefined) result.host = asciiLower(result.host)

  if (result.port !== undefined) {
    const fallback = result.scheme === undefined ? undefined : defaultPort(result.scheme)
    if (result.port === '' || (fallback !== undefined && result.port === fallback)) {
      result.port = undefined
    }
  }

  result.path = removeDotSegments(result.path)
  if (result.host !== undefined && result.path === '') result.path = '/'

  return result
}

/** Merge a relative reference path onto a base path, per RFC 3986 section 5.3. */
function merge(base, path) {
  if (base.host !== undefined && base.path === '') return `/${path}`
  const slash = base.path.lastIndexOf('/')
  return slash < 0 ? path : base.path.slice(0, slash + 1) + path
}

/**
 * Resolve a parsed reference against a parsed base, following the strict form
 * of RFC 3986 section 5.2.2. The result is returned normalized.
 */
export function resolve(base, reference) {
  const target = {}
  if (reference.scheme !== undefined) {
    target.scheme = reference.scheme
    copyAuthority(target, reference)
    target.path = removeDotSegments(reference.path)
    target.query = reference.query
  } else {
    if (reference.host !== undefined) {
      copyAuthority(target, reference)
      target.path = removeDotSegments(reference.path)
      target.query = reference.query
    } else {
      if (reference.path === '') {
        target.path = base.path
        target.query = reference.query !== undefined ? reference.query : base.query
      } else {
        target.path = reference.path.startsWith('/')
          ? removeDotSegments(reference.path)
          : removeDotSegments(merge(base, reference.path))
        target.query = reference.query
      }
      copyAuthority(target, base)
    }
    target.scheme = base.scheme
  }
  target.fragment = reference.fragment
  return normalize(target)
}

function copyAuthority(target, source) {
  target.authority = source.authority
  target.userinfo = source.userinfo
  target.host = source.host
  target.port = source.port
}
"}

