{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, compared as exact strings.
 *
 * Among equally long subsequences the one whose matches come earliest is
 * taken: walking both documents from the start, a match is taken whenever the
 * two current lines are equal, and otherwise the side whose remaining
 * subsequence is at least as long as the other's advances, the base winning
 * ties.
 */

/** @returns {Array<[number, number]>} pairs of matching indices (base, side). */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // suffix[i][j] = length of the LCS of base[i..] and side[j..]
  const suffix = []
  for (let i = 0; i <= n; i += 1) suffix.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = suffix[i]
    const next = suffix[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = base[i] === side[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (suffix[i + 1][j] >= suffix[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * Every stretch the subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines. Ends are exclusive.
 */
export function diffLines(base, side) {
  const matches = lcsMatches(base, side)
  const changes = []
  let baseAt = 0
  let sideAt = 0
  const push = (baseEnd, sideEnd) => {
    if (baseEnd > baseAt || sideEnd > sideAt) {
      changes.push({ baseStart: baseAt, baseEnd, sideStart: sideAt, sideEnd })
    }
  }
  for (const [b, s] of matches) {
    push(b, s)
    baseAt = b + 1
    sideAt = s + 1
  }
  push(base.length, side.length)
  return changes
}
"}

{"file_path":"src/parse.js","content":"/** Reading the three input documents. */

export const SEPARATOR = '%%%'

/**
 * Splits the input on newlines, drops the empty tail a trailing newline
 * leaves, and cuts the lines into documents at every `%%%` line.
 *
 * @returns {string[][]} one array of lines per document.
 */
export function parseDocuments(input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents
}
"}

