{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { parseDocuments } from './parse.js'
import { mergeRegions } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** @returns {string[]} the output lines of the `merge` and `merge2` modes. */
function renderMerge(regions, withBase) {
  const out = []
  for (const region of regions) {
    if (region.kind === 'conflict') {
      out.push('<<<<<<< mine', ...region.mine)
      if (withBase) out.push('||||||| base', ...region.base)
      out.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return out
}

/** @returns {string[]} the output lines of the `regions` mode. */
function renderRegions(regions) {
  return regions.map(region =>
    region.kind === 'conflict'
      ? `conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`
      : `${region.kind} ${region.lines.length}`,
  )
}

function main(argv) {
  const [mode] = argv
  if (argv.length !== 1 || !MODES.includes(mode)) fail('usage: cli.js merge|merge2|regions')

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }
  const documents = parseDocuments(input)
  if (documents.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = documents
  const regions = mergeRegions(mine, base, theirs)
  const lines = mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')

  process.stdout.write(lines.map(line => `${line}\n`).join(''))
  process.exitCode = regions.some(region => region.kind === 'conflict') ? 1 : 0
}

main(process.argv.slice(2))
"}

