        if (!isFinite(expResult)) return new ErrorValue('#DIV/0!');
        return expResult;
      default:
        return new ErrorValue('#ERR!');
    }
  }

  applyComparison(left, op, right) {
    if (isError(left)) return left;
    if (isError(right)) return right;

    // Compare values
    let result;

    // Both numbers
    if (typeof left === 'number' && typeof right === 'number') {
      switch (op) {
        case '=': result = left === right; break;
        case '<>': result = left !== right; break;
        case '<': result = left < right; break;
        case '<=': result = left <= right; break;
        case '>': result = left > right; break;
        case '>=': result = left >= right; break;
      }
    }
    // Both text
    else if (typeof left === 'string' && typeof right === 'string') {
      switch (op) {
        case '=': result = left === right; break;
        case '<>': result = left !== right; break;
        case '<': result = left < right; break;
        case '<=': result = left <= right; break;
        case '>': result = left > right; break;
        case '>=': result = left >= right; break;
      }
    }
    // Both booleans
    else if (left instanceof BooleanValue && right instanceof BooleanValue) {
      const lv = left.value;
      const rv = right.value;
      switch (op) {
        case '=': result = lv === rv; break;
        case '<>': result = lv !== rv; break;
        case '<': result = !lv && rv; break;
        case '<=': result = !lv || rv; break;
        case '>': result = lv && !rv; break;
        case '>=': result = lv || !rv; break;
      }
    }
    // Number vs text: number < text
    else if (typeof left === 'number' && typeof right === 'string') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = true; break;
        case '<=': result = true; break;
        case '>': result = false; break;
        case '>=': result = false; break;
      }
    }
    else if (typeof left === 'string' && typeof right === 'number') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    // Number vs boolean: number < boolean
    else if (typeof left === 'number' && right instanceof BooleanValue) {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = true; break;
        case '<=': result = true; break;
        case '>': result = false; break;
        case '>=': result = false; break;
      }
    }
    else if (left instanceof BooleanValue && typeof right === 'number') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    // Text vs boolean: text < boolean
    else if (typeof left === 'string' && right instanceof BooleanValue) {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = true; break;
        case '<=': result = true; break;
        case '>': result = false; break;
        case '>=': result = false; break;
      }
    }
    else if (left instanceof BooleanValue && typeof right === 'string') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    else {
      result = false;
    }

    return new BooleanValue(result);
  }
}
"}

