{"file_path":"src/formula.js","content":"/**
 * The formula language: a tokenizer and a recursive descent parser producing a
 * small syntax tree. Parsing never evaluates; a formula the grammar rejects is
 * reported by returning null.
 */

import { parseAddress } from './address.js'

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

/** Split a formula body into tokens, or null when a character is not one. */
export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < body.length && body[j] >= '0' && body[j] <= '9') j += 1
      if (body[j] === '.') {
        const start = j + 1
        let k = start
        while (k < body.length && body[k] >= '0' && body[k] <= '9') k += 1
        if (k === start) return null
        j = k
      }
      tokens.push({ type: 'number', value: Number(body.slice(i, j)) })
      i = j
      continue
    }
    if (isLetter(ch)) {
      let j = i
      while (j < body.length && (isLetter(body[j]) || (body[j] >= '0' && body[j] <= '9'))) j += 1
      tokens.push({ type: 'word', value: body.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = body.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if ('+-*/^=<>(),:'.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i += 1
      continue
    }
    return null
  }
  return tokens
}

function isLetter(ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')
}

class ParseFailure extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  isOp(value) {
    const token = this.peek()
    return token !== null && token.type === 'op' && token.value === value
  }

  next() {
    if (this.pos >= this.tokens.length) throw new ParseFailure()
    return this.tokens[this.pos++]
  }

  expectOp(value) {
    if (!this.isOp(value)) throw new ParseFailure()
    this.pos += 1
  }

  parseExpression() {
    let left = this.parseAdditive()
    while (true) {
      const token = this.peek()
      if (token === null || token.type !== 'op' || !COMPARISONS.includes(token.value)) break
      this.pos += 1
      const right = this.parseAdditive()
      left = { type: 'compare', op: token.value, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOp('+') || this.isOp('-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOp('*') || this.isOp('/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.isOp('^')) {
      this.pos += 1
      const right = this.parsePower()
      return { type: 'binary', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.next()
    if (token.type === 'number') return { type: 'number', value: token.value }
    if (token.type === 'op' && token.value === '(') {
      const inner = this.parseExpression()
      this.expectOp(')')
      return { type: 'group', inner }
    }
    if (token.type !== 'word') throw new ParseFailure()
    const word = token.value
    if (this.isOp('(')) {
      this.pos += 1
      const args = []
      if (this.isOp(')')) {
        this.pos += 1
      } else {
        while (true) {
          args.push(this.parseExpression())
          if (this.isOp(',')) {
            this.pos += 1
            continue
          }
          this.expectOp(')')
          break
        }
      }
      return { type: 'call', name: word, args }
    }
    if (this.isOp(':')) {
      this.pos += 1
      const end = this.next()
      if (end.type !== 'word') throw new ParseFailure()
      return { type: 'range', from: word, to: end.value }
    }
    if (word === 'TRUE') return { type: 'boolean', value: true }
    if (word === 'FALSE') return { type: 'boolean', value: false }
    return { type: 'ref', name: word, address: parseAddress(word) }
  }
}

/** Parse a formula body into a tree, or null when the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  const parser = new Parser(tokens)
  try {
    const tree = parser.parseExpression()
    if (parser.pos !== tokens.length) return null
    return tree
  } catch (error) {
    if (error instanceof ParseFailure) return null
    throw error
  }
}

/** The cells in range a range node covers, in column then row order. */
export function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const minCol = Math.min(from.col, to.col)
  const maxCol = Math.max(from.col, to.col)
  const minRow = Math.min(from.row, to.row)
  const maxRow = Math.max(from.row, to.row)
  for (let col = minCol; col <= maxCol; col++) {
    for (let row = minRow; row <= maxRow; row++) cells.push({ col, row })
  }
  return cells
}

/** Every cell a tree names directly, in column then row order, distinct. */
export function treeReferences(tree) {
  const seen = new Map()
  const walk = (node) => {
    switch (node.type) {
      case 'ref':
        if (node.address !== null) add(node.address)
        break
      case 'range': {
        const cells = rangeCells(node)
        if (cells !== null) for (const cell of cells) add(cell)
        break
      }
      case 'group':
        walk(node.inner)
        break
      case 'unary':
        walk(node.operand)
        break
      case 'binary':
      case 'compare':
        walk(node.left)
        walk(node.right)
        break
      case 'call':
        for (const arg of node.args) walk(arg)
        break
      default:
        break
    }
  }
  const add = (cell) => {
    const key = cell.col + ':' + cell.row
    if (!seen.has(key)) seen.set(key, { col: cell.col, row: cell.row })
  }
  walk(tree)
  return Array.from(seen.values()).sort((a, b) => a.col - b.col || a.row - b.row)
}
"}

