{"file_path":"src/sheet.js","content":"/**
 * Reading a sheet: one declaration per line, an address and the rest of the
 * line as the cell's content.
 */

import { cellKey, formatAddress, parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.sheetError = true
  }
}

function isBlank(ch) {
  return ch === ' ' || ch === '\t'
}

/** Split the input into lines, dropping the tail a trailing newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Read a sheet. Returns a Map of cell key to { col, row, content }, in the
 * order the cells were declared.
 */
export function readSheet(input) {
  const cells = new Map()
  const lines = splitLines(input)
  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const line = lines[index]
    let start = 0
    while (start < line.length && isBlank(line[start])) start += 1
    const rest = line.slice(start)
    if (rest === '' || rest[0] === '#') continue
    let end = 0
    while (end < rest.length && !isBlank(rest[end])) end += 1
    const word = rest.slice(0, end)
    let content = end
    while (content < rest.length && isBlank(rest[content])) content += 1
    const address = parseAddress(word.toUpperCase())
    if (address === null) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${word}`)
    }
    const key = cellKey(address.col, address.row)
    if (cells.has(key)) {
      const name = formatAddress(address.col, address.row)
      throw new SheetError(`error: line ${lineNumber}: cell ${name} is declared twice`)
    }
    cells.set(key, { col: address.col, row: address.row, content: rest.slice(content) })
  }
  return cells
}

/** The declared cells in column then row order. */
export function orderedCells(cells) {
  return Array.from(cells.values()).sort((a, b) => a.col - b.col || a.row - b.row)
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { formatAddress } from './address.js'
import { Sheet } from './evaluator.js'
import { treeReferences } from './formula.js'
import { SheetError, orderedCells, readSheet } from './sheet.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

async function readInput() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks).toString('utf8')
}

function renderValues(cells) {
  const sheet = new Sheet(cells)
  let out = ''
  for (const cell of orderedCells(cells)) {
    const value = sheet.valueAt(cell.col, cell.row)
    out += `${formatAddress(cell.col, cell.row)}=${formatValue(value)}\n`
  }
  return out
}

function renderDeps(cells) {
  const sheet = new Sheet(cells)
  let out = ''
  for (const cell of orderedCells(cells)) {
    const tree = sheet.treeOf(cell)
    const refs = tree === null ? [] : treeReferences(tree)
    let line = `${formatAddress(cell.col, cell.row)}:`
    for (const ref of refs) line += ' ' + formatAddress(ref.col, ref.row)
    out += line + '\n'
  }
  return out
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }
  const input = await readInput()
  let cells
  try {
    cells = readSheet(input)
  } catch (error) {
    if (error instanceof SheetError) {
      fail(error.message)
      return
    }
    throw error
  }
  const out = args[0] === 'values' ? renderValues(cells) : renderDeps(cells)
  process.stdout.write(out)
}

main()
"}

