const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

let mode = null
let workers = 0

if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
  mode = argv[0]
} else if (argv.length === 2 && argv[0] === 'pack') {
  mode = 'pack'
  if (!/^[1-9][0-9]*$/.test(argv[1])) fail('error: workers must be a positive integer', 2)
  workers = Number(argv[1])
} else {
  fail(USAGE, 2)
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const graph = parseGraph(input, fail)
const info = analyse(graph, fail)

const out = []

if (mode === 'waves') {
  const waves = []
  for (const name of graph.names) {
    const d = info.depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  for (let i = 0; i < waves.length; i++) {
    const list = (waves[i] || []).slice().sort(byName)
    out.push(`wave ${i}: ${list.join(' ')}`)
  }
  out.push(`total ${info.total}`)
} else if (mode === 'explain') {
  for (const name of graph.names.slice().sort(byName)) {
    out.push(`${name} start=${info.start.get(name)} finish=${info.finish.get(name)} depth=${info.depth.get(name)}`)
  }
  out.push(`total ${info.total}`)
} else {
  const result = pack(graph, info, workers)
  for (let i = 0; i < workers; i++) {
    let line = `worker ${i}:`
    for (const run of result.lanes[i]) line += ` ${run.name}@${run.start}-${run.finish}`
    out.push(line)
  }
  out.push(`makespan ${result.makespan}`)
}

function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

{"file_path":"src/parse.js","content":"const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Reads the build graph from the text of standard input.
 * Returns { names, cost, deps } where deps maps a name to a Set of names.
 */
export function parseGraph(text, fail) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const names = []
  const cost = new Map()
  const deps = new Map()
  const used = [] // names a dep line mentions, in input order

  const ensure = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`, 2)
      const name = words[1]
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`, 2)
      if (!COST.test(words[2])) fail(`error: line ${n}: cost must be a non-negative integer`, 2)
      if (cost.has(name)) fail(`error: line ${n}: task ${name} is declared twice`, 2)
      cost.set(name, Number(words[2]))
      names.push(name)
      ensure(name)
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`, 2)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`error: line ${n}: invalid task name ${words[w]}`, 2)
      }
      const target = words[1]
      used.push(target)
      ensure(target)
      for (let w = 2; w < words.length; w++) {
        used.push(words[w])
        deps.get(target).add(words[w])
      }
    } else {
      fail(`error: line ${n}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) fail(`error: unknown task ${name}`, 2)
  }

  return { names, cost, deps }
}
"}

{"file_path":"src/graph.js","content":"function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

/**
 * Rejects a cycle, then reports the depth, start, finish and priority of
 * every task along with the unlimited-worker makespan.
 */
export function analyse(graph, fail) {
  const { names, cost, deps } = graph
  const sorted = names.slice().sort(byName)

  const sortedDeps = new Map()
  for (const name of names) sortedDeps.set(name, Array.from(deps.get(name) || []).sort(byName))

  detectCycle(sorted, sortedDeps, fail)

  const order = topoOrder(sorted, sortedDeps)

  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  let total = 0
  for (const name of order) {
    let d = 0
    let s = 0
    for (const dep of sortedDeps.get(name)) {
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    const f = s + cost.get(name)
    finish.set(name, f)
    if (f > total) total = f
  }

  // priority: cost of the longest chain that begins at the task
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const name of names) {
    for (const dep of sortedDeps.get(name)) dependents.get(dep).push(name)
  }
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let best = 0
    for (const child of dependents.get(name)) best = Math.max(best, priority.get(child))
    priority.set(name, cost.get(name) + best)
  }

  return { depth, start, finish, priority, total }
}

function detectCycle(sorted, sortedDeps, fail) {
  const colour = new Map() // 1 = on the stack, 2 = done
  for (const root of sorted) {
    if (colour.get(root)) continue
    const path = [root]
    const stack = [{ node: root, i: 0 }]
    colour.set(root, 1)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = sortedDeps.get(frame.node)
      if (frame.i < list.length) {
        const next = list[frame.i++]
        const c = colour.get(next) || 0
        if (c === 1) {
          const cycle = path.slice(path.indexOf(next))
          cycle.push(next)
          fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
        } else if (c === 0) {
          colour.set(next, 1)
          path.push(next)
          stack.push({ node: next, i: 0 })
        }
      } else {
        colour.set(frame.node, 2)
        stack.pop()
        path.pop()
      }
    }
  }
}

function topoOrder(sorted, sortedDeps) {
  const done = new Set()
  const order = []
  for (const root of sorted) {
    if (done.has(root)) continue
    const stack = [{ node: root, i: 0 }]
    done.add(root)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const list = sortedDeps.get(frame.node)
      if (frame.i < list.length) {
        const next = list[frame.i++]
        if (!done.has(next)) {
          done.add(next)
          stack.push({ node: next, i: 0 })
        }
      } else {
        order.push(frame.node)
        stack.pop()
      }
    }
  }
  return order
}
"}

{"file_path":"src/pack.js","content":"function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

/** Simulates the graph on a fixed number of workers. */
export function pack(graph, info, workerCount) {
  const { names, cost, deps } = graph
  const lanes = []
  const free = []
  for (let i = 0; i < workerCount; i++) {
    lanes.push([])
    free.push(0)
  }

  const pending = names.slice().sort(byName)
  const done = new Map() // name -> finish time
  let time = 0
  let makespan = 0

  while (done.size < pending.length) {
    let started = false
    for (;;) {
      let worker = -1
      for (let i = 0; i < workerCount; i++) {
        if (free[i] <= time) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let choice = null
      for (const name of pending) {
        if (done.has(name)) continue
        let ready = true
        for (const dep of deps.get(name) || []) {
          const f = done.get(dep)
          if (f === undefined || f > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (choice === null || info.priority.get(name) > info.priority.get(choice)) choice = name
      }
      if (choice === null) break

      const start = time
      const finish = start + cost.get(choice)
      lanes[worker].push({ name: choice, start, finish })
      free[worker] = finish
      done.set(choice, finish)
      if (finish > makespan) makespan = finish
      started = true
    }

    if (done.size >= pending.length) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (free[i] > time && free[i] < next) next = free[i]
    }
    if (next === Infinity) {
      if (!started) break
      continue
    }
    time = next
  }

  return { lanes, makespan }
}
"}

