{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and reference resolution following
 * RFC 3986's generic syntax.
 *
 * A parsed reference is a plain object whose components are either a string
 * (the component is present, possibly empty) or undefined (absent). Keeping
 * that distinction is what lets `http://a/b?` and `http://a/b` print back the
 * way they came.
 */

const UNRESERVED = /[A-Za-z0-9\-._~]/
const HEX = /[0-9A-Fa-f]/

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21'
}

/** Thrown for a malformed percent-encoding; carries the component's name. */
export class UriError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 0x20) : ch
  }
  return out
}

/**
 * Split a URI reference into scheme, authority, path, query and fragment.
 * The authority, when present, is split further into userinfo, host and port.
 */
export function parse(reference) {
  let rest = reference
  let scheme

  const colon = rest.indexOf(':')
  if (colon !== -1) {
    const head = rest.slice(0, colon)
    if (!/[/?#]/.test(head)) {
      scheme = head
      rest = rest.slice(colon + 1)
    }
  }

  let fragment
  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  let query
  const question = rest.indexOf('?')
  if (question !== -1) {
    query = rest.slice(question + 1)
    rest = rest.slice(0, question)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const end = rest.search(/[/?#]/)
    if (end === -1) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, end)
      rest = rest.slice(end)
    }
  }

  const uri = { scheme, path: rest, query, fragment }
  if (authority !== undefined) Object.assign(uri, splitAuthority(authority))
  else Object.assign(uri, { authority: undefined, userinfo: undefined, host: undefined, port: undefined })
  return uri
}

/**
 * The userinfo is everything before the last `@`; the port is everything after
 * the first `:` that follows the last `]`; the host is what lies between.
 */
function splitAuthority(authority) {
  let userinfo
  let rest = authority

  const at = rest.lastIndexOf('@')
  if (at !== -1) {
    userinfo = rest.slice(0, at)
    rest = rest.slice(at + 1)
  }

  let port
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket + 1)
  if (colon !== -1) {
    port = rest.slice(colon + 1)
    rest = rest.slice(0, colon)
  }

  return { authority, userinfo, host: rest, port }
}

/** Rebuild the authority string from its three parts. */
function joinAuthority(uri) {
  if (uri.host === undefined) return undefined
  let authority = ''
  if (uri.userinfo !== undefined) authority += `${uri.userinfo}@`
  authority += uri.host
  if (uri.port !== undefined) authority += `:${uri.port}`
  return authority
}

/** Render a parsed reference back to a string. */
export function serialize(uri) {
  let out = ''
  if (uri.scheme !== undefined) out += `${uri.scheme}:`
  const authority = joinAuthority(uri)
  if (authority !== undefined) out += `//${authority}`
  out += uri.path
  if (uri.query !== undefined) out += `?${uri.query}`
  if (uri.fragment !== undefined) out += `#${uri.fragment}`
  return out
}

/**
 * Uppercase the hex digits of every `%XX` and decode the triplet when it
 * stands for an unreserved character. Throws `UriError` on a truncated one.
 */
function normalizePercent(text, component) {
  if (text === undefined) return undefined
  let out = ''
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const digits = text.slice(i + 1, i + 3)
    if (digits.length !== 2 || !HEX.test(digits[0]) || !HEX.test(digits[1])) {
      throw new UriError(component)
    }
    const upper = digits.toUpperCase()
    const decoded = String.fromCharCode(parseInt(upper, 16))
    out += UNRESERVED.test(decoded) ? decoded : `%${upper}`
    i += 2
  }
  return out
}

/** The components carrying percent-encodings, in the order they are checked. */
const PERCENT_COMPONENTS = ['path', 'userinfo', 'host', 'query', 'fragment']

/** Report a truncated percent-encoding, checking the components in order. */
export function checkPercent(uri) {
  for (const component of PERCENT_COMPONENTS) normalizePercent(uri[component], component)
}

/** Remove dot segments from a path, per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  const dropLastSegment = () => {
    const slash = output.lastIndexOf('/')
    output = slash === -1 ? '' : output.slice(0, slash)
  }

  while (input.length > 0) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = `/${input.slice(3)}`
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../')) {
      input = `/${input.slice(4)}`
      dropLastSegment()
    } else if (input === '/..') {
      input = '/'
      dropLastSegment()
    } else if (input === '.' || input === '..') input = ''
    else {
      const start = input[0] === '/' ? 1 : 0
      let next = input.indexOf('/', start)
      if (next === -1) next = input.length
      output += input.slice(0, next)
      input = input.slice(next)
    }
  }

  return output
}

/**
 * Normalize a parsed reference in place of a fresh copy: case of the scheme
 * and host, percent-encodings, the default port, and dot segments.
 */
export function normalize(uri) {
  const out = { ...uri }

  if (out.scheme !== undefined) out.scheme = asciiLower(out.scheme)

  for (const component of PERCENT_COMPONENTS) {
    out[component] = normalizePercent(out[component], component)
  }

  if (out.host !== undefined) out.host = asciiLower(out.host)

  if (out.port !== undefined) {
    const fallback = out.scheme === undefined ? undefined : DEFAULT_PORTS[out.scheme]
    if (out.port === '' || out.port === fallback) out.port = undefined
  }

  out.path = removeDotSegments(out.path)

  if (out.host !== undefined && out.path === '') out.path = '/'

  return out
}

/** Merge a relative path onto the base's path, per RFC 3986 section 5.3. */
function merge(base, path) {
  if (base.host !== undefined && base.path === '') return `/${path}`
  const slash = base.path.lastIndexOf('/')
  return slash === -1 ? path : base.path.slice(0, slash + 1) + path
}

/**
 * Resolve a reference against a base, per RFC 3986 section 5.2.2 in its strict
 * form: a reference that repeats the base's scheme stays an absolute URI.
 */
export function resolve(base, reference) {
  const target = { scheme: undefined, authority: undefined, userinfo: undefined, host: undefined, port: undefined, path: '', query: undefined, fragment: undefined }
  const takeAuthority = (from) => {
    target.authority = from.authority
    target.userinfo = from.userinfo
    target.host = from.host
    target.port = from.port
  }

  if (reference.scheme !== undefined) {
    target.scheme = reference.scheme
    takeAuthority(reference)
    target.path = removeDotSegments(reference.path)
    target.query = reference.query
  } else {
    if (reference.host !== undefined) {
      takeAuthority(reference)
      target.path = removeDotSegments(reference.path)
      target.query = reference.query
    } else {
      if (reference.path === '') {
        target.path = base.path
        target.query = reference.query !== undefined ? reference.query : base.query
      } else {
        target.path = removeDotSegments(
          reference.path.startsWith('/') ? reference.path : merge(base, reference.path)
        )
        target.query = reference.query
      }
      takeAuthority(base)
    }
    target.scheme = base.scheme
  }

  target.fragment = reference.fragment
  return target
}
"}

