{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parse, serialize, normalize, resolve, checkPercent, UriError } from './uri.js'

/** A record failure: the message is printed as it stands, prefixed per line. */
class RecordError extends Error {}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Split the input into records, dropping the empty tail a `\n` leaves. */
function toRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  return chunks
}

async function readAll(stream) {
  stream.setEncoding('utf8')
  let input = ''
  for await (const chunk of stream) input += chunk
  return input
}

function normalizeRecord(record) {
  const uri = parse(record)
  checkPercent(uri)
  return serialize(normalize(uri))
}

function resolveRecord(record) {
  const space = record.indexOf(' ')
  if (space === -1) throw new RecordError('expected a base and a reference')

  const base = parse(record.slice(0, space))
