{"file_path":"src/parse.js","content":"/**
 * Turning the text of an election into candidates and ballots.
 */

export class ElectionError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function fail(message) {
  throw new ElectionError(message)
}

/**
 * Split the input the way the specification asks: on newlines, dropping the one
 * empty tail that a trailing newline leaves behind.
 */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse an election. Returns { candidates, ballots }, where a ballot is
 * { count, names }. Throws an ElectionError carrying the exact message for the
 * first problem found.
 */
export function parseElection(input) {
  const lines = splitLines(input)
  let candidates = null
  const declared = new Set()
  const ballots = []
  let sawBallot = false

  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const text = lines[index].trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null || sawBallot) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = words.slice(1)
      if (names.length === 0) fail(`line ${lineNumber}: expected candidates <name>...`)
      for (const name of names) {
        if (!NAME.test(name)) fail(`line ${lineNumber}: invalid candidate name ${name}`)
        if (declared.has(name)) fail(`line ${lineNumber}: candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names
      continue
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      sawBallot = true
      if (words.length < 3) fail(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      const count = words[1]
      if (!COUNT.test(count)) fail(`line ${lineNumber}: count must be a positive integer`)
      const names = words.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!declared.has(name)) fail(`line ${lineNumber}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${lineNumber}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(count), names })
      continue
    }

    fail(`line ${lineNumber}: unknown directive ${directive}`)
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

