{"file_path":"src/count.js","content":"/**
 * The instant-runoff count itself, including the backwards tie-break used to
 * choose who leaves at the end of a round.
 */

/** Compare two names by code point. */
export function compareNames(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

/**
 * Of the candidates tied for fewest, choose the one to eliminate by walking the
 * rounds counted so far from the first onwards. The first round whose counts
 * are not all equal keeps only the fewest, and those survivors are compared the
 * same way from the first round again. A tie no round separates goes to the
 * name that sorts last.
 */
function chooseLoser(tied, history) {
  for (let round = 0; round < history.length; round += 1) {
    const counts = tied.map((name) => history[round].get(name))
    const fewest = Math.min(...counts)
    const most = Math.max(...counts)
    if (fewest !== most) {
      const survivors = tied.filter((name) => history[round].get(name) === fewest)
      return chooseLoser(survivors, history)
    }
  }
  return tied.slice().sort(compareNames)[tied.length - 1]
}

/**
 * Run the election. Returns { rounds, winner }, where each round holds the
 * continuing candidates' counts, the exhausted total and who was eliminated.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }

    let active = 0
    for (const votes of counts.values()) active += votes

    const round = { counts, exhausted, eliminated: null }
    rounds.push(round)
    history.push(counts)

    if (active === 0) return { rounds, winner: null }

    for (const [name, votes] of counts) {
      if (votes * 2 > active) return { rounds, winner: name }
    }

    let fewest = Infinity
    for (const votes of counts.values()) fewest = Math.min(fewest, votes)
    const tied = []
    for (const [name, votes] of counts) {
      if (votes === fewest) tied.push(name)
    }
    const loser = tied.length === 1 ? tied[0] : chooseLoser(tied, history)
    round.eliminated = loser
    continuing.delete(loser)
  }
}
"}

