{"file_path":"src/report.js","content":"/**
 * Rendering a finished count in either mode.
 */

import { compareNames } from './count.js'

function outcome(winner) {
  return winner === null ? 'no winner\n' : `winner ${winner}\n`
}

/** The `rounds` mode: every round, with the eliminations between them. */
export function renderRounds(result) {
  let out = ''
  result.rounds.forEach((round, index) => {
    const entries = Array.from(round.counts.entries()).sort((a, b) => {
      if (a[1] !== b[1]) return b[1] - a[1]
      return compareNames(a[0], b[0])
    })
    const parts = entries.map(([name, votes]) => `${name}=${votes}`)
    parts.push(`exhausted=${round.exhausted}`)
    out += `round ${index + 1}: ${parts.join(' ')}\n`
    if (round.eliminated !== null) out += `eliminated ${round.eliminated}\n`
  })
  return out + outcome(result.winner)
}

/** The `tally` mode: how many rounds ran, and the outcome. */
export function renderTally(result) {
  return `rounds ${result.rounds.length}\n` + outcome(result.winner)
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { ElectionError, parseElection } from './parse.js'
import { runElection } from './count.js'
import { renderRounds, renderTally } from './report.js'

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'rounds' && mode !== 'tally') die('usage: cli.js rounds|tally')

  let election
  try {
    election = parseElection(readStdin())
  } catch (error) {
    if (error instanceof ElectionError) die(error.message)
    throw error
  }

  const result = runElection(election.candidates, election.ballots)
  process.stdout.write(mode === 'rounds' ? renderRounds(result) : renderTally(result))
}

main(process.argv.slice(2))
"}

