{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { ElectionError } from './errors.js'
import { parseElection } from './parse.js'
import { countElection } from './count.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    throw new ElectionError('usage: cli.js rounds|tally')
  }
  const election = parseElection(readStdin())
  const result = countElection(election)
  return mode === 'rounds' ? formatRounds(result) : formatTally(result)
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (error) {
  if (!(error instanceof ElectionError)) throw error
  process.stderr.write(`error: ${error.message}\n`)
  process.exit(2)
}
"}

