{"file_path":"src/parser.js","content":"/**
 * Parse a URI reference according to RFC 3986.
 * Returns an object with: scheme, authority, path, query, fragment
 * Each field is either absent (undefined) or present (string, possibly empty)
 */
export function parseUri(uriRef) {
  const result = {
    scheme: undefined,
    authority: undefined,
    path: '',
    query: undefined,
    fragment: undefined
  };

  let str = uriRef;

  // Extract fragment from end (optional # to end)
  const fragmentIdx = str.indexOf('#');
  if (fragmentIdx !== -1) {
    result.fragment = str.slice(fragmentIdx + 1);
    str = str.slice(0, fragmentIdx);
  }

  // Extract query (optional ? to end)
  const queryIdx = str.indexOf('?');
  if (queryIdx !== -1) {
    result.query = str.slice(queryIdx + 1);
    str = str.slice(0, queryIdx);
  }

  // Extract scheme (optional, up to first : not preceded by /, ?, or #)
  let schemeEndIdx = -1;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === ':') {
      schemeEndIdx = i;
      break;
    }
    if (ch === '/' || ch === '?' || ch === '#') {
      break;
    }
  }

  if (schemeEndIdx !== -1) {
    result.scheme = str.slice(0, schemeEndIdx);
    str = str.slice(schemeEndIdx + 1);
  }

  // Extract authority and path
  // Authority is introduced by // and runs to next /, ?, or #
  if (str.startsWith('//')) {
    str = str.slice(2);
    let authorityEnd = str.length;
    for (let i = 0; i < str.length; i++) {
      if (str[i] === '/' || str[i] === '?' || str[i] === '#') {
        authorityEnd = i;
        break;
      }
    }
    result.authority = str.slice(0, authorityEnd);
    str = str.slice(authorityEnd);
  }

  // Everything remaining is the path
  result.path = str;

  return result;
}

/**
 * Parse authority into userinfo, host, and port.
 * userinfo: everything before the last @
 * port: everything after the first : that follows the last ]
 * host: what's in between
 */
export function parseAuthority(authority) {
  if (!authority) return { userinfo: undefined, host: '', port: undefined };

  let userinfo = undefined;
  let hostPort = authority;

  const lastAt = authority.lastIndexOf('@');
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt);
    hostPort = authority.slice(lastAt + 1);
  }

  let port = undefined;
  let host = hostPort;

  // Find the last ] (for IPv6)
  const lastBracket = hostPort.lastIndexOf(']');
  const colonIdx = hostPort.indexOf(':');

  if (colonIdx !== -1) {
    // If there's a ] and the : is after it, this : is for the port
    if (lastBracket !== -1 && colonIdx > lastBracket) {
      port = hostPort.slice(colonIdx + 1);
      host = hostPort.slice(0, colonIdx);
    } else if (lastBracket === -1) {
      // No IPv6, so first : is the port separator
      port = hostPort.slice(colonIdx + 1);
      host = hostPort.slice(0, colonIdx);
    }
  }

  return { userinfo, host, port };
}

/**
 * Reconstruct a URI from parsed components
 */
export function reconstructUri(parsed) {
  let result = '';

  if (parsed.scheme !== undefined) {
    result += parsed.scheme + ':';
  }

  if (parsed.authority !== undefined) {
    result += '//' + parsed.authority;
  }

  result += parsed.path;

  if (parsed.query !== undefined) {
    result += '?' + parsed.query;
  }

  if (parsed.fragment !== undefined) {
    result += '#' + parsed.fragment;
  }

  return result;
}
"}

