{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'

import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'
import { formatRound } from './report.js'

const args = process.argv.slice(2)
const mode = args[0]

// The command takes exactly one argument, either `rounds` or `tally`.
if (args.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
  fail('error: usage: cli.js rounds|tally')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let out = ''
try {
  const { candidates, ballots } = parseElection(input)
  const result = runElection(candidates, ballots)

  if (mode === 'rounds') {
    for (const round of result.rounds) out += formatRound(round)
  } else {
    out += `rounds ${result.rounds.length}\n`
  }

  out += result.winner === null ? 'no winner\n' : `winner ${result.winner}\n`
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.message)
}

process.stdout.write(out)

/** Reports a failure on standard error and stops with status 2. */
function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}
"}

