{"file_path":"src/parse.js","content":"/**
 * Reading an election: the `candidates` declaration and the `ballot` lines,
 * with every rule the input has to keep.
 */

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

/** A rejected input, carrying the exact message the command reports. */
export class ParseError extends Error {}

function reject(message) {
  throw new ParseError(message)
}

/**
 * Reads the text of an election, returning the declared candidates in the order
 * given and the ballots in the order recorded.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  // A trailing newline leaves an empty tail that is not a line.
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const number = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const directive = words[0]
    const rest = words.slice(1)

    if (directive === 'candidates') {
      if (candidates !== null) {
        reject(`error: line ${number}: candidates must be declared once, before any ballot`)
      }
      if (rest.length === 0) {
        reject(`error: line ${number}: expected candidates <name>...`)
      }
      for (const name of rest) {
        if (!NAME.test(name)) {
          reject(`error: line ${number}: invalid candidate name ${name}`)
        }
        if (declared.has(name)) {
          reject(`error: line ${number}: candidate ${name} is declared twice`)
        }
        declared.add(name)
      }
      candidates = rest.slice()
    } else if (directive === 'ballot') {
      if (candidates === null) {
        reject(`error: line ${number}: candidates must be declared once, before any ballot`)
      }
      if (rest.length < 2) {
        reject(`error: line ${number}: expected ballot <count> <candidate>...`)
      }
      if (!COUNT.test(rest[0])) {
        reject(`error: line ${number}: count must be a positive integer`)
      }
      const count = Number(rest[0])
      const choices = rest.slice(1)
      const seen = new Set()
      for (const name of choices) {
        if (!declared.has(name)) {
          reject(`error: line ${number}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          reject(`error: line ${number}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, choices })
    } else {
      reject(`error: line ${number}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) reject('error: no candidates')

  return { candidates, ballots }
}
"}

